"""Extra independent check using a DPLL solver on larger instances."""
import itertools, random, json
from reduce import reduce
from problems import Sat, ThreeSat

def solve_dpll(instance):
    m = instance["num_vars"]
    clauses = [frozenset(c) for c in instance["clauses"]]
    if any(len(c) == 0 for c in clauses):
        return False
    def rec(clauses, assign):
        # unit propagation
        clauses = [set(c) for c in clauses]
        assign = dict(assign)
        changed = True
        while changed:
            changed = False
            for c in clauses:
                if len(c) == 0:
                    return False
                if len(c) == 1:
                    lit = next(iter(c))
                    v = abs(lit); val = lit > 0
                    if v in assign and assign[v] != val:
                        return False
                    if v not in assign:
                        assign[v] = val
                        changed = True
            new = []
            for c in clauses:
                sat = False
                rest = set()
                for lit in c:
                    v = abs(lit); val = lit > 0
                    if v in assign:
                        if assign[v] == val:
                            sat = True; break
                    else:
                        rest.add(lit)
                if sat:
                    continue
                if len(rest) == 0:
                    return False
                new.append(rest)
            clauses = new
            if not clauses:
                return True
        # pick a variable
        lit = next(iter(clauses[0]))
        v = abs(lit)
        for val in (True, False):
            a2 = dict(assign); a2[v] = val
            if rec(clauses, a2):
                return True
        return False
    return rec(clauses, {})

def solve(instance):
    if instance["num_vars"] <= 12:
        # brute force for ground truth on small
        m = instance["num_vars"]
        for bits in itertools.product((False, True), repeat=m):
            if all(any((bits[abs(l)-1] if l>0 else not bits[abs(l)-1]) for l in c) for c in instance["clauses"]):
                return True
        return False
    return solve_dpll(instance)

rng = random.Random(999)
run = passed = 0
fails = []
for trial in range(3000):
    m = rng.randint(3, 8)
    n = rng.randint(1, 6)
    clauses = []
    for _ in range(n):
        L = rng.randint(3, 15)
        clauses.append([rng.choice([1,-1])*rng.randint(1,m) for _ in range(L)])
    inst = {"num_vars": m, "clauses": clauses}
    try:
        Sat.validate(inst)
    except Exception as e:
        continue
    src = solve(inst)
    out = reduce(inst)
    run += 1
    try:
        ThreeSat.validate(out)
    except Exception as e:
        fails.append(f"invalid target {inst} -> {e}"); continue
    tgt = solve(out)
    if src != tgt:
        fails.append(f"mismatch {inst} src={src} tgt={tgt} out={out}")
    else:
        passed += 1

# also test all-false long clauses and mixed
for k in range(4, 16):
    inst = {"num_vars": k, "clauses": [[-(i+1) for i in range(k)]]}
    run += 1
    src = solve(inst); out = reduce(inst); tgt = solve(out)
    if src == tgt: passed += 1
    else: fails.append(f"long all-neg k={k} mismatch")

print(f"extra run={run} passed={passed}")
for f in fails[:10]: print("FAIL:", f)
